PRAGMA foreign_keys=ON;
CREATE TABLE settings (id INTEGER PRIMARY KEY CHECK(id=1), json TEXT NOT NULL);
CREATE TABLE credentials (name TEXT PRIMARY KEY, encrypted TEXT NOT NULL);
CREATE TABLE admins (id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,password TEXT NOT NULL,recovery TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE sessions (hash TEXT PRIMARY KEY,admin_id TEXT NOT NULL REFERENCES admins(id),csrf TEXT NOT NULL,expires_at INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE catalog (sku TEXT PRIMARY KEY,json TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE sync_state (name TEXT PRIMARY KEY,json TEXT NOT NULL);
CREATE TABLE products (id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE,sku TEXT NOT NULL UNIQUE,parent_id TEXT,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',image TEXT NOT NULL DEFAULT '',price INTEGER NOT NULL CHECK(price>0),minimum INTEGER NOT NULL DEFAULT 0,stock INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 0,featured INTEGER NOT NULL DEFAULT 0,supplier TEXT,verified INTEGER NOT NULL DEFAULT 0,offers TEXT NOT NULL DEFAULT '[]',blocks TEXT NOT NULL DEFAULT '[]',color TEXT NOT NULL DEFAULT '#173d35',form_color TEXT NOT NULL DEFAULT '#f3f0e9',revision INTEGER NOT NULL DEFAULT 1);
CREATE INDEX products_public ON products(active,featured);
CREATE INDEX products_supplier ON products(supplier,active);
CREATE TABLE orders (id TEXT PRIMARY KEY,ref TEXT NOT NULL UNIQUE,idempotency TEXT NOT NULL UNIQUE,request_hash TEXT NOT NULL,customer TEXT NOT NULL,supplier TEXT NOT NULL,quote TEXT NOT NULL,attribution TEXT NOT NULL,matching TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending_confirmation',sync_status TEXT NOT NULL DEFAULT 'not_sent',shipping_status TEXT,financial_status TEXT,mowarid_id TEXT,remote TEXT,last_error TEXT,created_at TEXT NOT NULL,confirmed_at TEXT,delivered_at TEXT,delivery_time_source TEXT,next_poll INTEGER NOT NULL DEFAULT 0);
CREATE INDEX orders_created ON orders(created_at);
CREATE INDEX orders_work ON orders(status,sync_status);
CREATE INDEX orders_poll ON orders(next_poll) WHERE mowarid_id IS NOT NULL;
CREATE TABLE order_items (id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES orders(id),product_id TEXT NOT NULL,sku TEXT NOT NULL,quantity INTEGER NOT NULL,unit_price INTEGER NOT NULL,snapshot TEXT NOT NULL);
CREATE INDEX order_items_order ON order_items(order_id);
CREATE TABLE jobs (id TEXT PRIMARY KEY,type TEXT NOT NULL,order_id TEXT REFERENCES orders(id),status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,run_at INTEGER NOT NULL,lease_until INTEGER NOT NULL DEFAULT 0,lease_token TEXT,last_error TEXT,created_at TEXT NOT NULL);
CREATE INDEX jobs_due ON jobs(status,run_at);
CREATE UNIQUE INDEX jobs_order_type ON jobs(type,order_id) WHERE order_id IS NOT NULL;
CREATE TABLE cities (id INTEGER PRIMARY KEY CHECK(id=1),json TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE ad_spend (id TEXT PRIMARY KEY,source TEXT NOT NULL,campaign TEXT NOT NULL,date TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0),UNIQUE(source,campaign,date));
CREATE INDEX ad_spend_date ON ad_spend(date);
CREATE TABLE audit (id TEXT PRIMARY KEY,admin_id TEXT,action TEXT NOT NULL,target TEXT,created_at TEXT NOT NULL);
CREATE TABLE limits (key TEXT PRIMARY KEY,count INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE visits (key TEXT PRIMARY KEY,date TEXT NOT NULL,source TEXT NOT NULL,campaign TEXT NOT NULL);
CREATE INDEX visits_campaign ON visits(date,source,campaign);
CREATE TABLE metrics (date TEXT PRIMARY KEY,reads INTEGER NOT NULL DEFAULT 0,writes INTEGER NOT NULL DEFAULT 0);
CREATE TABLE media (id TEXT PRIMARY KEY,url TEXT NOT NULL,size INTEGER NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL,created_at TEXT NOT NULL);
